13	// The two routing paths that a colon-joined key cannot tell apart, and the two
14	// that a NUL-joined key cannot tell apart. nonce is 7 for all of them.
15	var ambiguousColonPaths = [][2]string{{"a:b", "c"}, {"a", "b:c"}}
16	var ambiguousNULPaths = [][2]string{{"a\x00b", "c"}, {"a", "b\x00c"}}
17	
18	// TestConsumeTokenIsInjective guards the encoding itself: the four ambiguous
19	// paths plus a same-path repeat produce four distinct tokens and one equal
20	// pair, never relying on forbidding or rewriting chain names.
21	func TestConsumeTokenIsInjective(t *testing.T) {
22		seen := map[string]string{}
23		add := func(label, from, to string, nonce uint64) consumeToken {
24			tok := newConsumeToken(from, to, nonce)
25			key := tok.marshal()
26			if other, dup := seen[key]; dup {
27				t.Fatalf("%s and %s share one consumption token: %q -> %q nonce %d", label, other, from, to, nonce)
28			}
29			seen[key] = label
30			return tok
31		}
32		t1 := add("colon-1", ambiguousColonPaths[0][0], ambiguousColonPaths[0][1], 7)
33		add("colon-2", ambiguousColonPaths[1][0], ambiguousColonPaths[1][1], 7)
34		t3 := add("nul-1", ambiguousNULPaths[0][0], ambiguousNULPaths[0][1], 7)
35		add("nul-2", ambiguousNULPaths[1][0], ambiguousNULPaths[1][1], 7)
36	
37		if t1 == t3 {
38			t.Fatalf("distinct paths collapsed: %+v == %+v", t1, t3)
39		}
40		again := newConsumeToken(ambiguousColonPaths[0][0], ambiguousColonPaths[0][1], 7)
41		if again != t1 {
42			t.Fatalf("the same (from,to,nonce) must compare equal")
43		}
44		if again.marshal() != t1.marshal() {
45			t.Fatalf("the same triple must serialize identically")
46		}
47	}
48	
49	// TestVerifyAmbiguousPathsDistinct covers the in-memory entry point: both
50	// ambiguous pairs deliver, and only a genuine repeat of the same triple is a
51	// replay.
52	func TestVerifyAmbiguousPathsDistinct(t *testing.T) {
53		headers := map[string]Header{}
54		for _, pair := range append(append([][2]string{}, ambiguousColonPaths...), ambiguousNULPaths...) {
55			headers[pair[0]] = Header{Chain: pair[0], Height: 100, Trusted: true}
56		}
57		consumed := map[string]bool{}
58		msgs := []Message{
59			{ID: "c1", From: "a:b", To: "c", Nonce: 7, ProofAt: 10},
60			{ID: "c2", From: "a", To: "b:c", Nonce: 7, ProofAt: 10},
61			{ID: "n1", From: "a\x00b", To: "c", Nonce: 7, ProofAt: 10},
62			{ID: "n2", From: "a", To: "b\x00c", Nonce: 7, ProofAt: 10},
63		}
64		for _, m := range msgs {
65			d := Verify(headers, m, consumed)
66			if d.Status != "delivered" {
67				t.Fatalf("distinct path %s rejected as %s: %s", m.ID, d.Status, d.Reason)
68			}
69		}
70		if d := Verify(headers, msgs[2], consumed); d.Status != "rejected" ||
71			!strings.Contains(d.Reason, "replay") {
72			t.Fatalf("genuine repeat must be a replay, got %s: %s", d.Status, d.Reason)
73		}
74	}
