76	// TestQueueAmbiguousPathsDistinct drives both pairs through the durable queue
77	// in one advance: all four succeed concurrently-in-order, while a fifth
78	// message on an already consumed triple is a replay pointing at the real
79	// winner. Relationships survive restart and log compaction.
80	func TestQueueAmbiguousPathsDistinct(t *testing.T) {
81		dir := t.TempDir()
82		q, err := Open(dir)
83		if err != nil {
84			t.Fatal(err)
85		}
86		for _, chain := range []string{"a:b", "a", "a\x00b"} {
87			if err := q.RegisterSource(chain); err != nil {
88				t.Fatal(err)
89			}
90			if err := q.UpsertHeader(Header{Chain: chain, Height: 100, Trusted: true}); err != nil {
91				t.Fatal(err)
92			}
93		}
94		type sub struct{ id, from, to string }
95		subs := []sub{
96			{"c1", "a:b", "c"},
97			{"c2", "a", "b:c"},
98			{"n1", "a\x00b", "c"},
99			{"n2", "a", "b\x00c"},
100			{"dup", "a:b", "c"}, // exact same triple as c1
101		}
102		for _, s := range subs {
103			if _, err := q.Submit(env(s.id, s.from, s.to, 7, 10, 0)); err != nil {
104				t.Fatal(err)
105			}
106		}
107		rep, err := q.Advance(1000)
108		if err != nil {
109			t.Fatal(err)
110		}
111		got := map[string]Result{}
112		for _, r := range rep.Results {
113			got[r.ID] = r
114		}
115		for _, s := range subs[:4] {
116			if got[s.id].Status != StatusSuccess {
117				t.Fatalf("%s (%q -> %q) must succeed, got %+v", s.id, s.from, s.to, got[s.id])
118			}
119		}
120		if got["dup"].Status != StatusReplay || !strings.Contains(got["dup"].Reason, "c1") {
121			t.Fatalf("dup must be replay attributed to c1, got %+v", got["dup"])
122		}
123		if len(q.consumed) != 4 {
124			t.Fatalf("want exactly 4 consumed triples, got %d: %v", len(q.consumed), q.consumed)
125		}
126		// Queries keep the full, unmodified chain names.
127		if r, _ := q.Query("n1"); r.From != "a\x00b" || r.To != "c" {
128			t.Fatalf("NUL chain name rewritten: %q -> %q", r.From, r.To)
129		}
130		if r, _ := q.Query("c2"); r.From != "a" || r.To != "b:c" {
131			t.Fatalf("colon chain name rewritten: %q -> %q", r.From, r.To)
132		}
133	
134		// Force a compaction, then reopen: all four successes stay distinct and
135		// terminal, and a new id on either consumed triple still replays.
136		if err := q.store.compact(q.snapshot()); err != nil {
137			t.Fatal(err)
138		}
139		if err := q.Close(); err != nil {
140			t.Fatal(err)
141		}
142		q2, err := Open(dir)
143		if err != nil {
144			t.Fatalf("reopen compacted dir: %v", err)
145		}
146		defer q2.Close()
147		if len(q2.consumed) != 4 {
148			t.Fatalf("consumed triples lost across compaction: %v", q2.consumed)
149		}
150		for _, s := range subs[:4] {
151			if r := statusOf(t, q2, s.id); r.Status != StatusSuccess {
152				t.Fatalf("%s lost success after compaction: %s", s.id, r.Status)
153			}
154		}
155		if _, err := q2.Submit(env("c1-again", "a:b", "c", 7, 10, 0)); err != nil {
156			t.Fatal(err)
157		}
158		rep, err = q2.Advance(2000)
159		if err != nil {
160			t.Fatal(err)
161		}
162		var again Result
163		for _, r := range rep.Results {
164			if r.ID == "c1-again" {
165				again = r
166			}
167		}
168		if again.Status != StatusReplay || !strings.Contains(again.Reason, "c1") {
169			t.Fatalf("same triple under new id must replay at c1 after reopen, got %+v", again)
170		}
171	}
