277	// Plain result records stay incremental: unknown/terminal targets, attempts
278	// jumps and backwards processing times are all rejected, with the result
279	// category and id named.
280	func TestResultSpecificAcceptance(t *testing.T) {
281		t.Run("unknown id", func(t *testing.T) {
282			entries := []*logEntry{
283				{T: kindResult, Now: 1000, ID: "ghost", Status: StatusExpired, Reason: "x", Attempts: 1},
284			}
285			assertRecoveryCorrupt(t, entries, "result for unknown id", `"ghost"`)
286		})
287	
288		t.Run("terminal id", func(t *testing.T) {
289			entries := append(successRecoveryBase(), successRecoveryRecord(kindResult))
290			again := &logEntry{
291				T: kindResult, Now: 2000, ID: "m", Status: StatusExpired, Reason: "later", Attempts: 2,
292			}
293			entries = append(entries, again)
294			assertRecoveryCorrupt(t, entries, "result for terminal id", `"m"`)
295		})
296	
297		t.Run("attempts must advance by one", func(t *testing.T) {
298			r := waitingRecoveryRecord(kindResult)
299			r.Attempts = 3 // pending record has zero attempts; the jump 0 -> 3 is invalid
300			r.NextRetry = 5000
301			entries := append(waitingRecoveryBase(), r)
