35	// casedSubmitLog frames the leading version record plus one synthetic submit
36	// body whose payload member is spelled by the caller, so the field-name casing
37	// is exactly what is on disk.
38	func casedSubmitLog(t *testing.T, body string) []byte {
39		t.Helper()
40		var raw []byte
41		raw = append(raw, logMagic...)
42		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
43		raw = append(raw, encodeFrame([]byte(body))...)
44		return raw
45	}
