47	// casedSubmitBody wraps a literal payload JSON member in an otherwise normal
48	// seq-0 submit record.
49	func casedSubmitBody(payloadMember string) string {
50		return `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,` + payloadMember + `}`
51	}
