53	// flipOneByte returns a payload differing from want in exactly one byte.
54	func flipOneByte(want string) string {
55		if len(want) == 0 {
56			return "x"
57		}
58		b := []byte(want)
59		b[len(b)-1] ^= 1
60		return string(b)
61	}
