63	// TestPayloadSoleRepresentationRestoresSameBytesAcrossCasings drives a record
64	// carrying exactly one payload representation through conventional, upper and
65	// mixed-case field names and requires identical restored content.
66	func TestPayloadSoleRepresentationRestoresSameBytesAcrossCasings(t *testing.T) {
67		const helloB64 = "aGVsbG8=" // "hello"
68		const ffB64 = "/w=="        // single byte 0xFF
69	
70		cases := []struct {
71			name   string
72			member string // literal payload JSON member
73			want   string
74		}{
75			// Plain text is read as the saved text, regardless of field casing.
76			{"plain conventional", `"payload":"hello"`, "hello"},
77			{"plain upper", `"PAYLOAD":"hello"`, "hello"},
78			{"plain capitalized", `"Payload":"hello"`, "hello"},
79			{"plain mixed", `"pAyLoAd":"hello"`, "hello"},
80	
81			// A sole base64 representation restores its original bytes, including
82			// invalid UTF-8 and ordinary text, under every casing.
83			{"base64 conventional raw byte", `"payloadB64":"` + ffB64 + `"`, "\xff"},
84			{"base64 upper raw byte", `"PAYLOADB64":"` + ffB64 + `"`, "\xff"},
85			{"base64 capitalized raw byte", `"PayloadB64":"` + ffB64 + `"`, "\xff"},
86			{"base64 mixed raw byte", `"pAyLoAdb64":"` + ffB64 + `"`, "\xff"},
87			{"base64 upper text bytes", `"PAYLOADB64":"` + helloB64 + `"`, "hello"},
88		}
89		for _, tc := range cases {
90			t.Run(tc.name, func(t *testing.T) {
91				dir := t.TempDir()
92				raw := casedSubmitLog(t, casedSubmitBody(tc.member))
93				writeRawLog(t, dir, raw)
94	
95				q := reopen(t, dir)
96				defer q.Close()
97	
98				got, ok := q.Query("m")
99				if !ok {
100					t.Fatal("restored message missing")
101				}
102				// Byte-exact: a re-cased sole base64 field must never come back as a
103				// U+FFFD replacement rune or an empty payload.
104				if got.Payload != tc.want {
105					t.Fatalf("restored payload mismatch:\nwant % x\ngot  % x", tc.want, got.Payload)
106				}
107	
108				// An identical resubmit of the unterminated message returns the
109				// existing record and adds nothing. The envelope mirrors the
110				// synthetic record's routing fields (from/to/nonce/proofAt).
111				env := Envelope{Message: Message{
112					ID: "m", From: "a", To: "b", Nonce: 1,
113					Payload: tc.want, ProofAt: 10,
114				}}
115				echo, err := q.Submit(env)
116				if err != nil {
117					t.Fatalf("identical resubmit must return the existing record: %v", err)
118				}
119				if echo.Msg.Message.Payload != tc.want {
120					t.Fatalf("resubmit echo payload = % x, want % x", echo.Msg.Message.Payload, tc.want)
121				}
122				if len(q.Queries()) != 1 {
123					t.Fatalf("identical resubmit added a record: %d rows", len(q.Queries()))
124				}
125	
126				// A one-byte payload change is a content conflict and keeps the
127				// original message and its bytes.
128				bad := env
129				bad.Message.Payload = flipOneByte(tc.want)
130				if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
131					t.Fatalf("one-byte payload change must be ErrConflict, got %v", err)
132				}
133				after, ok := q.Query("m")
134				if !ok || after.Payload != tc.want {
135					t.Fatalf("original payload not preserved after conflict: ok=%v % x", ok, after.Payload)
136				}
137				if len(q.Queries()) != 1 {
138					t.Fatalf("conflicting resubmit added a record: %d rows", len(q.Queries()))
139				}
140			})
141		}
142	}
