286				}
287				if strings.Contains(msg, "both payload and payloadB64") {
288					t.Fatalf("encoding failure must not be reported as a representation conflict: %q", msg)
289				}
290				got, rerr := os.ReadFile(filepath.Join(dir, logName))
291				if rerr != nil {
292					t.Fatal(rerr)
293				}
294				if string(got) != string(raw) {
295					t.Fatalf("corrupt log was modified: want %d bytes, got %d bytes", len(raw), len(got))
296				}
297			})
298		}
299	}
300	
301	// TestPayloadReCasedCorruptionAfterNormalRecords verifies a complete offending
302	// frame is never treated as an unwritten torn tail: placed after normal
303	// records, the whole directory is refused and every log byte — including the
304	// good leading message — is preserved, so none of the earlier records can be
305	// queried.
306	func TestPayloadReCasedCorruptionAfterNormalRecords(t *testing.T) {
307		dir := t.TempDir()
308		var raw []byte
309		raw = append(raw, logMagic...)
310		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
311		// One good, ordinary message at seq 0.
312		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
313			T: kindSubmit, Seq: 0, ID: "ok", From: "a", To: "b", Nonce: 1,
314			Payload: "normal", ProofAt: 10,
315		}))...)
316	
317		t.Run("dual representation", func(t *testing.T) {
318			log := append(append([]byte(nil), raw...), encodeFrame([]byte(
319				`{"t":"submit","seq":1,"id":"bad","from":"a","to":"b","nonce":2,"proofAt":10,"PAYLOAD":"","payloadB64":"/w=="}`))...)
320			writeRawLog(t, dir, log)
321			assertCorruptUntouched(t, dir, log, "both payload and payloadB64")
322		})
