324		t.Run("undecodable base64", func(t *testing.T) {
325			log := append(append([]byte(nil), raw...), encodeFrame([]byte(
326				`{"t":"submit","seq":1,"id":"bad","from":"a","to":"b","nonce":2,"proofAt":10,"PAYLOADB64":"%not-base64%"}`))...)
327			writeRawLog(t, dir, log)
328			assertCorruptUntouched(t, dir, log, "undecodable payloadB64")
329		})
