332	// TestSplitKeyPresenceIsCaseInsensitive guards the shared presence layer
333	// directly: every presence-tracked plain/base64 pair must recognize its keys
334	// under re-cased spellings, so a re-cased sole base64 key is present (and
335	// decodes) while a re-cased plain key next to a canonical base64 key reads as
336	// two representations.
337	func TestSplitKeyPresenceIsCaseInsensitive(t *testing.T) {
338		pairs := []struct {
339			name     string
340			plainKey string
341			b64Key   string
342			spec     splitFieldSpec
343			rawB64   string // decodes to a single valid byte 0x78 ("x")
344		}{
345			{"root", "root", "rootB64", splitFields.root, "eA=="},
346			{"payload", "payload", "payloadB64", splitFields.payload, "eA=="},
347			{"to", "to", "toB64", splitFields.to, "eA=="},
348			{"consumeTo", "consumeTo", "consumeToB64", splitFields.consumeTo, "eA=="},
349		}
350		for _, p := range pairs {
351			t.Run(p.name, func(t *testing.T) {
352				upper := func(k string) string { return strings.ToUpper(k) }
353	
354				// A sole upper-case base64 key is present and decodes to its bytes.
355				sole := `{"` + upper(p.b64Key) + `":"` + p.rawB64 + `"}`
356				var e logEntry
357				if err := json.Unmarshal([]byte(sole), &e); err != nil {
358					t.Fatal(err)
359				}
360				if !e.present[p.b64Key] || e.present[p.plainKey] {
361					t.Fatalf("sole %s presence wrong: %+v", upper(p.b64Key), e.present)
362				}
363				if got, err := p.spec.decode(&e); err != nil || got != "x" {
364					t.Fatalf("sole re-cased base64 decode: got %q err=%v", got, err)
365				}
366	
367				// A re-cased plain key next to the canonical base64 key is the clash.
368				both := `{"` + upper(p.plainKey) + `":"x","` + p.b64Key + `":"` + p.rawB64 + `"}`
369				var e2 logEntry
370				if err := json.Unmarshal([]byte(both), &e2); err != nil {
371					t.Fatal(err)
372				}
373				if !e2.present[p.plainKey] || !e2.present[p.b64Key] {
374					t.Fatalf("dual-key presence wrong: %+v", e2.present)
375				}
376				if _, err := p.spec.decode(&e2); err == nil || err.Error() != p.spec.bothErr {
377					t.Fatalf("re-cased dual keys: want %q, got %v", p.spec.bothErr, err)
378				}
379			})
380		}
381	}
