1	package relayproof
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"math"
8		"os"
9		"path/filepath"
10		"strings"
11		"testing"
12	)
13	
14	// These tests pin down the architecture-independent framing rule: the log's
15	// uint32 declared length is read as a full unsigned value and the frame end is
16	// computed without integer overflow, so a 32-bit build judges a huge declared
17	// length exactly like a 64-bit one. A declared length a narrow int cannot hold
18	// (2^31, 2^32-1) — or one whose sum with its position would overflow it — must
19	// never wrap the record range back inside the file: the leading version record
20	// so declared is corrupt (ErrCorrupt, file untouched), while the same shape as
21	// the final record after a valid version record is the ordinary torn tail and
22	// is truncated, preserving every acknowledged record before it.
23	
24	// hugeLengthHeader returns the four-byte big-endian frame length header
25	// declaring a payload of n bytes.
26	func hugeLengthHeader(n uint32) []byte {
27		var hdr [frameHeaderSize]byte
28		binary.BigEndian.PutUint32(hdr[:], n)
29		return hdr[:]
30	}
31	
32	// A first record whose declared body/checksum bytes are not all present is
33	// corrupt no matter how large the declared length is: the open must fail with
34	// ErrCorrupt, return no usable queue, and leave every byte of the log in
35	// place — never truncate the log to a magic-only shell or fabricate a version
36	// record. This holds for lengths that turn negative in a 32-bit int and for
37	// lengths whose end offset would overflow one.
38	func TestHugeDeclaredVersionLengthIsCorrupt(t *testing.T) {
39		cases := map[string]uint32{
40			"2^31 (negative as int32)":           1 << 31,
41			"2^32-1 (max uint32)":                math.MaxUint32,
42			"positive but end overflows int32":   0x7FFFFFF0,
43			"positive, position pushes end over": 0x7FFFFF00,
44		}
45		for name, n := range cases {
46			t.Run(name, func(t *testing.T) {
47				dir := t.TempDir()
48				data := append([]byte(logMagic), hugeLengthHeader(n)...)
49				// Only a token of the declared body is present.
50				data = append(data, '{')
51				writeRawLog(t, dir, data)
52	
53				q, err := Open(dir)
54				if !errors.Is(err, ErrCorrupt) {
55					if q != nil {
56						q.Close()
57					}
58					t.Fatalf("want ErrCorrupt, got %v (queue=%v)", err, q != nil)
59				}
60				if q != nil {
61					q.Close()
62					t.Fatalf("corrupt open must not return a usable queue")
63				}
64				if !strings.Contains(err.Error(), "incomplete version record") {
65					t.Fatalf("error must name the incomplete version record, got %q", err)
66				}
67				assertLogUntouched(t, dir, data)
68	
69				// A repeated open keeps failing and still alters nothing.
70				q2, err2 := Open(dir)
71				if !errors.Is(err2, ErrCorrupt) || q2 != nil {
72					if q2 != nil {
73						q2.Close()
74					}
75					t.Fatalf("repeated open must keep failing with ErrCorrupt, got %v", err2)
76				}
77				assertLogUntouched(t, dir, data)
78			})
79		}
80	}
81	
82	// assertLogUntouched requires queue.log in dir to equal want byte for byte.
83	func assertLogUntouched(t *testing.T, dir string, want []byte) {
84		t.Helper()
85		got, err := os.ReadFile(filepath.Join(dir, logName))
86		if err != nil {
87			t.Fatal(err)
88		}
89		if string(got) != string(want) {
90			t.Fatalf("log was modified: want %d bytes, got %d bytes", len(want), len(got))
91		}
92	}
93	
94	// With an intact, checksum-valid version record, a final record whose declared
95	// length runs far past the end of the file is the ordinary torn tail of an
96	// unacknowledged write — however huge the declaration. Only that record is
97	// dropped: every complete record before it is recovered, the saved success and
98	// its nonce consumption survive, the never-written message does not appear,
99	// and the queue keeps working. The declared length must not be misjudged just
100	// because a 32-bit int cannot hold it.
101	func TestHugeDeclaredTailLengthStillTruncates(t *testing.T) {
102		for _, n := range []uint32{1 << 31, math.MaxUint32, 0x7FFFFFF0} {
103			t.Run(fmt.Sprintf("declared length %d", n), func(t *testing.T) {
104				dir := t.TempDir()
105				q, err := Open(dir)
106				if err != nil {
107					t.Fatal(err)
108				}
109				if err := q.RegisterSource("a"); err != nil {
110					t.Fatal(err)
111				}
112				if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
113					t.Fatal(err)
114				}
115				if _, err := q.Submit(env("m1", "a", "b", 1, 10, 0)); err != nil {
116					t.Fatal(err)
117				}
118				if _, err := q.Advance(1000); err != nil {
119					t.Fatal(err)
120				}
121				if err := q.Close(); err != nil {
122					t.Fatal(err)
123				}
124	
125				raw, err := os.ReadFile(filepath.Join(dir, logName))
126				if err != nil {
127					t.Fatal(err)
128				}
129	
130				// A final record declares an enormous body that never arrives.
131				d := t.TempDir()
132				torn := append(append([]byte(nil), raw...), hugeLengthHeader(n)...)
133				torn = append(torn, 'x')
134				writeRawLog(t, d, torn)
135	
136				qt, err := Open(d)
137				if err != nil {
138					t.Fatalf("huge declared tail length must truncate and open: %v", err)
139				}
140				defer qt.Close()
141				if r := statusOf(t, qt, "m1"); r.Status != StatusSuccess {
142					t.Fatalf("acknowledged success lost: %+v", r)
143				}
144				if winner := qt.consumed[newConsumeToken("a", "b", 1)]; winner != "m1" {
145					t.Fatalf("consumed nonce not restored: %q", winner)
146				}
147				if qt.nextSeq != 1 {
148					t.Fatalf("nextSeq must resume after the last intact submit, got %d", qt.nextSeq)
149				}
150				// The log was cut back to exactly the acknowledged prefix.
151				assertLogUntouched(t, d, raw)
152				// The recovered queue stays fully usable.
153				if _, err := qt.Submit(env("m2", "a", "b", 2, 10, 0)); err != nil {
154					t.Fatalf("recovered queue must accept new submits: %v", err)
155				}
156				if _, err := qt.Advance(2000); err != nil {
157					t.Fatal(err)
158				}
159				if r := statusOf(t, qt, "m2"); r.Status != StatusSuccess {
160					t.Fatalf("new message should deliver on recovered queue: %+v", r)
161				}
162			})
163		}
164	}
