1646	// setSuccessConsumption fills a success entry's consumed triple and attributes
1647	// it to the successful message id. It is the one fill rule shared by the
1648	// incremental result path and the compacted-state path, so a success state and
1649	// its nonce consumption are always written together, as one record, with the
1650	// same plain/base64 source, destination and id encoding.
1651	func setSuccessConsumption(e *logEntry, id string, token *consumeToken) {
1652		e.setConsumeFrom(token.from)
1653		e.setConsumeTo(token.to)
1654		e.ConsumeNonce = token.nonce
1655		e.setConsumeBy(id)
1656	}
1657	
1658	// newStatusEntry builds one post-processing record from the same message-record
1659	// fields both save paths persist: kindResult for the incremental appendOutcome
1660	// path (one outcome per processing), kindState for the compacted snapshot (the
1661	// message's current status after >=1 attempts). The kind differs only in T and
1662	// in what replay accepts; every populated field — processing time, status,
1663	// reason, attempt count, the waiting retry instant and, on success, the
1664	// consumed triple attributed to this message — is chosen by one rule here, so
1665	// the two paths can never drift on status meaning, the plain-vs-raw-bytes
1666	// reason/id encoding, or when a nonce is consumed. nextRetry is the saturated
1667	// retry instant for a waiting result and zero otherwise (omitted on disk).
1668	func newStatusEntry(kind string, now, nextRetry int64, attempts int, id, status, reason string, consume *consumeToken) (*logEntry, error) {
1669		e := &logEntry{
1670			T: kind, Now: now,
1671			Status: status, Attempts: attempts, NextRetry: nextRetry,
1672		}
1673		e.setID(id)
1674		e.setReason(reason)
1675		if status == StatusSuccess {
1676			if consume == nil {
1677				return nil, fmt.Errorf("internal error: success result for %q missing nonce consumption", id)
1678			}
1679			setSuccessConsumption(e, id, consume)
1680		}
1681		return e, nil
1682	}
1683	
1684	// appendOutcome records one processing result. Every result carries the
1685	// processing time, the post-attempt attempt count and the resulting status and
1686	// reason; a waiting result additionally carries the retry instant the queue
1687	// layer already computed and saturated, so the log never carries an overflowed
1688	// negative schedule. On success the consumed triple
1689	// (consumeFrom/consumeTo/consumeNonce) and its consumer are part of the same
1690	// durable record, committing together atomically; oc.consume is nil for every
1691	// non-success status. The entry itself is built by newStatusEntry, the same
1692	// constructor the compacted snapshot uses.
1693	func (s *store) appendOutcome(now int64, rec *Record, attempts int, nextRetry int64, oc outcome) error {
1694		e, err := newStatusEntry(kindResult, now, nextRetry, attempts,
1695			rec.Msg.Message.ID, oc.status, oc.reason, oc.consume)
1696		if err != nil {
1697			return err
1698		}
1699		return s.append(e)
1700	}
